// ============================================================
// BLOGS DE LEYES/ABOGADOS (IDs reales del Google Sheet)
// Estrategia: Lead capture widget + AdSense optimization
// ============================================================

const BLOGS_LEYES = [
  {
    id: '4185821469969358370',
    nombre: 'Abogados bienes raíces USA',
    nicho: 'real-estate',
    cta_texto: 'Free Consultation',
    cta_subtitulo: 'Real Estate Attorney',
    telefono: '+1 (800) 000-0000',
    color: { grad: '135deg,#1a2a6c,#2d5fa6', text: '#1a2a6c', bg: '#eaf0fb' }
  },
  {
    id: '6030388327366455376',
    nombre: 'Abogados de accidente Orlando',
    nicho: 'accidente-orlando',
    cta_texto: 'Free Consultation',
    cta_subtitulo: 'Car Accident Attorney · Orlando, FL',
    telefono: '+1 (407) 000-0000',
    color: { grad: '135deg,#7d0000,#c0392b', text: '#7d0000', bg: '#fdf0f0' }
  },
  {
    id: '3503300865393838043',
    nombre: 'Abogados de familia USA',
    nicho: 'familia',
    cta_texto: 'Consulta Gratis',
    cta_subtitulo: 'Abogado de Familia',
    telefono: '+1 (800) 000-0000',
    color: { grad: '135deg,#1a6c3c,#27ae60', text: '#1a6c3c', bg: '#eafaf1' }
  },
  {
    id: '3388695765945711848',
    nombre: 'Litigios USA',
    nicho: 'litigios',
    cta_texto: 'Free Case Review',
    cta_subtitulo: 'Litigation Attorney',
    telefono: '+1 (800) 000-0000',
    color: { grad: '135deg,#2c3e50,#34495e', text: '#2c3e50', bg: '#f0f3f4' }
  }
];

const MAX_POSTS = 10;
return BLOGS_LEYES.map(blog => ({ json: { blog, MAX_POSTS } }));

const response = $input.item.json;
const blog = $('Config Blogs de Leyes').item.json.blog;

// Solo procesar posts que NO tengan ya el widget de leads
const posts = (response.items || []).filter(p =>
  !(p.content||'').includes('LEAD-WIDGET') &&
  !(p.content||'').includes('ADSENSE-SLOT')
);

return posts.map(post => {
  const contenido = post.content || '';
  const c = blog.color;

  // -------------------------------------------------------
  // 1. WIDGET DE LEAD CAPTURE (arriba del contenido)
  // -------------------------------------------------------
  const leadWidget = `
<!-- LEAD-WIDGET: ${blog.nicho} -->
<div style="background:linear-gradient(${c.grad});border-radius:14px;padding:24px 28px;margin:0 0 32px;font-family:Arial,sans-serif;box-shadow:0 4px 16px rgba(0,0,0,.15);max-width:700px">
  <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap">
    <div style="font-size:44px;flex-shrink:0">⚖️</div>
    <div style="flex:1;min-width:200px">
      <p style="color:rgba(255,255,255,.8);font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 4px">Habla con un experto</p>
      <h3 style="color:#fff;font-size:19px;font-weight:800;margin:0 0 6px;line-height:1.3">${blog.cta_subtitulo}</h3>
      <p style="color:rgba(255,255,255,.85);font-size:13px;margin:0">Consulta confidencial sin costo. Respuesta en 24 horas.</p>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px;flex-shrink:0">
      <a href="tel:${blog.telefono.replace(/[^+\d]/g,'')}" style="display:inline-block;background:#fff;color:${c.text};font-weight:800;font-size:14px;padding:11px 22px;border-radius:8px;text-decoration:none;text-align:center">
        📞 Llamar ahora
      </a>
      <a href="https://wa.me/${blog.telefono.replace(/[^\d]/g,'')}?text=Hola%2C%20necesito%20una%20consulta" target="_blank" rel="noopener"
         style="display:inline-block;background:#25d366;color:#fff;font-weight:800;font-size:13px;padding:10px 22px;border-radius:8px;text-decoration:none;text-align:center">
        💬 WhatsApp
      </a>
    </div>
  </div>
</div>
<!-- FIN LEAD-WIDGET -->`;

  // -------------------------------------------------------
  // 2. ADSENSE SLOT PLACEHOLDER (medio del artículo)
  // Reemplaza data-ad-slot con tu slot real de AdSense
  // -------------------------------------------------------
  const adsenseMid = `
<!-- ADSENSE-SLOT: mid-article -->
<div style="margin:32px 0;text-align:center">
  <ins class="adsbygoogle"
       style="display:block"
       data-ad-client="ca-pub-1913674678143092"
       data-ad-slot="SLOT_MID_ARTICLE"
       data-ad-format="auto"
       data-full-width-responsive="true"></ins>
  <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
</div>
<!-- FIN ADSENSE-SLOT -->`;

  // -------------------------------------------------------
  // 3. LEAD CAPTURE FINAL (al pie del artículo)
  // -------------------------------------------------------
  const leadBottom = `
<!-- LEAD-WIDGET-BOTTOM: ${blog.nicho} -->
<div style="background:${c.bg};border:2px solid ${c.text};border-radius:14px;padding:28px;margin:40px 0 0;font-family:Arial,sans-serif;max-width:700px">
  <h3 style="color:${c.text};font-size:20px;font-weight:800;margin:0 0 8px">¿Necesitas asesoría legal? 📋</h3>
  <p style="color:#444;font-size:14px;margin:0 0 16px;line-height:1.6">Completa el formulario y un abogado especializado se pondrá en contacto contigo en menos de 24 horas. <strong>Primera consulta sin costo.</strong></p>
  <div style="display:flex;gap:10px;flex-wrap:wrap">
    <a href="tel:${blog.telefono.replace(/[^+\d]/g,'')}" style="flex:1;min-width:160px;display:inline-block;background:${c.text};color:#fff;font-weight:800;font-size:14px;padding:13px 20px;border-radius:8px;text-decoration:none;text-align:center">📞 ${blog.cta_texto}</a>
    <a href="https://wa.me/${blog.telefono.replace(/[^\d]/g,'')}" target="_blank" rel="noopener" style="flex:1;min-width:160px;display:inline-block;background:#25d366;color:#fff;font-weight:800;font-size:14px;padding:13px 20px;border-radius:8px;text-decoration:none;text-align:center">💬 WhatsApp</a>
  </div>
  <p style="color:#aaa;font-size:11px;margin:12px 0 0">Confidencial · Sin compromiso · Respuesta en 24h</p>
</div>
<!-- FIN LEAD-WIDGET-BOTTOM -->`;

  // Insertar AdSense a mitad del contenido
  const mitad = Math.floor(contenido.length / 2);
  const corte = contenido.indexOf('</p>', mitad);
  const punto = corte > 0 ? corte + 4 : mitad;
  const contenidoConAds = contenido.slice(0, punto) + adsenseMid + contenido.slice(punto);

  return {
    json: {
      blogId: blog.id,
      blogNombre: blog.nombre,
      postId: post.id,
      titulo: post.title,
      contenidoActualizado: leadWidget + contenidoConAds + leadBottom
    }
  };
});
